            if (agentExecution.PublicSummaryOption.IsSet && agentExecution.PublicSummary == null)
                throw new ArgumentNullException(nameof(agentExecution.PublicSummary), "Property is required for class AgentExecution.");

            writer.WriteString("agent_id", agentExecution.AgentId);

            writer.WriteString("id", agentExecution.Id);

            writer.WriteString("run_id", agentExecution.RunId);

            writer.WriteString("started_at", agentExecution.StartedAt);

            writer.WriteString("task_id", agentExecution.TaskId);

            if (agentExecution.ArtifactIdsOption.IsSet)
