            }
            if (agentExecution.ChildExecutionIdsOption.IsSet)
            {
                writer.WritePropertyName("child_execution_ids");
                JsonSerializer.Serialize(writer, agentExecution.ChildExecutionIds, jsonSerializerOptions);
            }
            if (agentExecution.CompletedAtOption.IsSet)
                if (agentExecution.CompletedAtOption.Value != null)
                    writer.WriteString("completed_at", agentExecution.CompletedAt);
                else
                    writer.WriteNull("completed_at");

            if (agentExecution.CurrentActivityOption.IsSet)
                if (agentExecution.CurrentActivityOption.Value != null)
                    writer.WriteString("current_activity", agentExecution.CurrentActivity);
                else
                    writer.WriteNull("current_activity");

            if (agentExecution.DelegationDepthOption.IsSet)
                writer.WriteNumber("delegation_depth", agentExecution.DelegationDepthOption.Value!.Value);

            if (agentExecution.ErrorOption.IsSet)
                if (agentExecution.ErrorOption.Value != null)
                    writer.WriteString("error", agentExecution.Error);
                else
                    writer.WriteNull("error");

            if (agentExecution.ModelNameOption.IsSet)
                writer.WriteString("model_name", agentExecution.ModelName);

            if (agentExecution.ModelProviderOption.IsSet)
                writer.WriteString("model_provider", agentExecution.ModelProvider);

            if (agentExecution.NotesOption.IsSet)
            {
                writer.WritePropertyName("notes");
                JsonSerializer.Serialize(writer, agentExecution.Notes, jsonSerializerOptions);
            }
            if (agentExecution.ObjectiveOption.IsSet)
